// 一個指標在某一期的判定：dir=up（越高越好）或 down（越低越好）；base 是前幾期的中位數
function shapeList(input) {
  var rows = rowsOf(input.raw), nowMs = nowOf(input);
  var loops = [];
  var red = 0, yel = 0, off = 0, latest = '';
  rows.forEach(function (row) {
    var c = cardOf(row);
    if (!c.id) return;
    var h = c.health, lamp = c.status === 'reserved' ? 'gray' : (h ? h.lamp : 'gray');
    var pills = [];
    if (c.status === 'reserved') {
      var n0 = c.ready_check.filter(function (r) { return r && r.a === 'yes'; }).length;
      pills.push({ text: '未開', tone: 'gray' });
      pills.push({ text: '檢查表 ' + n0 + '/' + (c.ready_check.length || 9), tone: 'gray' });
      off++;
      loops.push({ id: c.id, name: c.name || c.short || c.id, sub: [c.short, '預留，還沒立案'].filter(Boolean).join('・'), lamp: 'gray', kv: str(c.north_star && c.north_star.note) || '開工第一步：填迴圈卡、跑啟動檢查表。', trend: [], pills: pills });
      return;
    }
    if (!h) {
      pills.push({ text: '還沒有心跳', tone: 'gray' });
      loops.push({ id: c.id, name: c.name, sub: [c.short, c.cadence].filter(Boolean).join('・'), lamp: 'gray', kv: '心跳排程還沒跑過，燈號待判定。', trend: [], pills: pills });
      return;
    }
    if (lamp === 'red') red++; else if (lamp === 'yellow') yel++;
    if (h.computed_at && h.computed_at > latest) latest = h.computed_at;
    (h.stuck || []).forEach(function (k) { pills.push({ text: CELL_NAMES[k] + '格停擺', tone: 'red' }); });
    var nRed = Object.keys(h.metrics || {}).filter(function (k) { return h.metrics[k].level === 'red'; }).length;
    var nYel = Object.keys(h.metrics || {}).filter(function (k) { return h.metrics[k].level === 'yellow'; }).length;
    if (nRed) pills.push({ text: '指標跌破門檻 ' + nRed, tone: 'red' });
    if (nYel) pills.push({ text: '指標偏低 ' + nYel, tone: 'yellow' });
    var ck = h.checklist || { yes: 0, total: c.ready_check.length };
    pills.push({ text: '檢查表 ' + ck.yes + '/' + (ck.total || 9), tone: ck.total && ck.yes === ck.total ? 'green' : 'red' });
    if (h.last_progress) pills.push({ text: '最後進度 ' + h.last_progress.days + ' 天前（' + CELL_NAMES[h.last_progress.cell] + '）', tone: 'gray' });
    var ns = c.north_star || {};
    var hl = h.headline;
    var kv = '主指標「' + (str(ns.name) || '未定') + '」' + (ns.value == null || ns.value === '' ? '量不到' : fmtN(num(ns.value))) + (hl ? '　・　' + hl.name + ' ' + hl.line : '');
    var trend = hl && h.curves && h.curves[hl.id] ? h.curves[hl.id].slice(-12).map(function (p) { return p.value; }) : [];
    loops.push({ id: c.id, name: c.name, sub: [c.short, c.cadence].filter(Boolean).join('・'), lamp: lamp, kv: kv, trend: trend, pills: pills });
  });
  var order = { red: 0, yellow: 1, green: 2, gray: 3 };
  loops.sort(function (a, b) { return order[a.lamp] - order[b.lamp]; });
  var sum = loops.length + ' 個迴圈：' + red + ' 紅燈、' + yel + ' 黃燈、' + off + ' 未開' + (latest ? '　・　心跳最近一次 ' + latest.slice(0, 16).replace('T', ' ') + ' UTC' : '');
  return { success: true, surface: { summary: sum, status: '', loops: loops, details: [] } };
}

