// 一個指標在某一期的判定：dir=up（越高越好）或 down（越低越好）；base 是前幾期的中位數
function cellState(c, nowMs) {
  c = isObj(c) ? c : {};
  var hb = num(c.heartbeat_days), days = daysSince(c.last, nowMs);
  var s = { level: 'green', days: days, heartbeat: hb, text: '' };
  if (!str(c.last)) { s.level = 'red'; s.text = '從沒更新過'; }
  else if (hb == null) { s.level = 'gray'; s.text = '上次更新 ' + days + ' 天前／沒有心跳'; }
  else if (days > hb) { s.level = 'red'; s.text = '上次更新 ' + days + ' 天前，超過心跳 ' + hb + ' 天'; }
  else s.text = '上次更新 ' + days + ' 天前／心跳 ' + hb + ' 天';
  return s;
}
var HEAD_TONE = { red: 'red', yellow: 'yellow', green: 'green', gray: 'gray' };
function hbText(st) { return st ? st.text : '從沒更新過'; }

// list 畫面：所有迴圈一列一個
function expRow(e) {
  return { n: str(e.n), what: str(e.what), metric: str(e.metric), change: str(e.from) + ' → ' + str(e.to), due: str(e.due), ticket: str(e.ticket) };
}
// detail 畫面：一個迴圈的四格（details 是 0 或 1 個元素，畫面用清單樣板決定要不要畫）
function shapeDetail(input) {
  var rows = rowsOf(input.raw), nowMs = nowOf(input);
  if (!rows.length) return { success: false, error: '找不到這個迴圈（' + str(input.loop, 80) + '）' };
