  var lamp = c.status === 'reserved' ? 'gray' : (h.lamp || 'gray');
  var det = { title: (c.name || c.id) + (c.short ? '（' + c.short + '）' : ''), lamp: lamp };
  var reasons = (h.reasons || []).map(function (r) { return r.text; });
  det.callout = reasons.length ? '要看的事：' + reasons.join('；') : (c.status === 'reserved' ? '這個迴圈預留中，還沒立案。' : (h.computed_at ? '目前沒有異常。' : '心跳排程還沒跑過，燈號待判定。'));
  det.notify_note = str(h.notify_note);
  function head(k) {
    var st = h.cells && h.cells[k] ? h.cells[k] : cellState(c.cells[k], nowMs);
    return { title: CELL_NAMES[k], hb: hbText(st), tone: HEAD_TONE[st.level] || 'gray' };
  }
  // 觀察
  var obsRows = c.metrics.filter(isObj).map(function (m) {
