    var lv = st ? st.level : 'gray';
    return { name: str(m.name) || str(m.id), value: st && st.value != null ? fmtN(st.value) : '—', rule: st && st.line ? st.line : '—', state: { text: TONE_NAME[lv] || '未判定', tone: lv }, source: str(m.source), puller: str(m.puller), auto: m.auto === true ? '自動' : '手動／沒有' };
  });
