    var notes = Array.isArray(curveMetric.notes) ? curveMetric.notes.filter(isObj).map(function (n) { return { at: str(n.at), text: str(n.text) }; }) : [];
    curves.push({ title: str(curveMetric.name) + '（逐期；虛線＝紅線）', points: h.curves[curveMetric.id], notes: notes,
      legend: [{ tone: 'green', text: '正常' }, { tone: 'yellow', text: '黃燈（比前期中位數少 ' + Math.round(DEF_YELLOW * 100) + '% 以上）' }, { tone: 'red', text: '紅燈（少 ' + Math.round(DEF_RED * 100) + '% 以上）' }] });
